/* Stand-ins for game functions that are not decompiled yet (stubs generated by scripts/sp_missing.py). */
#pragma once

struct SpMissing {
    const char *name;     /* original function name */
    const char *module;   /* original source file (src/ac/acctrl) or "sdk" */
};

/* Reports the missing function and ends the program. */
[[noreturn]] void sp_missing(const SpMissing *fn);
